finding.text:
declare @strKey nvarchar(3000), @strDetailKey nvarchar(3000), @userlogin varchar(32), @p_status int; set @strDetailKey = '' select @userlogin = username from vdmnv where user_id_0 = @@userId SELECT @p_status = CASE WHEN @status = 1 THEN 1 ELSE 5 END;
IF @userlogin IS NULL BEGIN set @strKey = 'ngay_hop between ''' + convert(char(8), @ngay_ct1, 112) + ''' and ''' + convert(char(8), @ngay_ct2, 112) + ''' and ' + @strFinding + ' and 1=0' END ELSE BEGIN set @strKey = 'ngay_hop between ''' + convert(char(8), @ngay_ct1, 112) + ''' and ''' + convert(char(8), @ngay_ct2, 112) + ''' and ' + @strFinding set @strKey = @strKey + ' and ma_cuochop in (select ma_cuochop from cuochopacp where ma_nv = ''' + ISNULL(@userlogin, '') + ''' and status = ' + CONVERT(varchar(11), @p_status) + ')' END
exec ISWIFTStoreTableLoading '@@table', '@@fieldKey', '@@fields', @@fieldOrder, '', '', ' left join sysunit b on a.unit_id = b.unit_id left join dmlcuochop c on a.ma_lcuochop = c.ma_lcuochop', 'b.ma_unit, c.ten_lcuochop', '@@key', @strKey, @@filterKey, '', @pageIndex, 50, @@admin, @@userId --@@columnFilterKey

js.text:

function grid$qlcuochopApprove(f){
  this.constructor(f);
}
grid$qlcuochopApprove.prototype = new DirEvent();
grid$qlcuochopApprove.prototype.afterInit = function(renderType){
  var p = this._dir;
  console.log(p.options._status);
	if (p.options._status == 1 || p.options._status == 5) {
		p.find(".toolbar-approve").attr(
			'title',
			p.msg(p.options._status == 1 ? 'approve' : 'undo')
		);
	}
}
grid$qlcuochopApprove.prototype.beforeButtonGridClick = function (id, gindex) {

  var msg, p = this._dir, g = p.grid(gindex), dt = g.data, fees = p.selectedItems(), xstatus = p.options._status;
  switch (id) {
    case 'approve':
		msg = (xstatus == 1) ? p.msg('msg1') : (xstatus == 5) ? p.msg('msg2') : '';
		if (fees.count() > 0)
        $.question(msg, $.msg.get("QuestionTitle"), p, function (q, v) {
          q._close();
          if (v){
            p.request('Approve', '', [["tblKeys", "T", fees.sqlval()], ['xstatus', 'I', xstatus]], function(pp, d, run){
              if (run) {
                p._refresh();
                p.clearSelectedItems();
              }
            });
          }
        });
      return false;
      break;
    default:
      break;
  }
  return true;
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
